CREATE OR REPLACE FUNCTION public.app_admin_list_pending_opportunities()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
