    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_review_opportunity(p_opportunity_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_role TEXT;
  v_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  v_role := public.app_get_current_role();
  IF v_role <> 'admin' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_admin');
  END IF;

  IF p_decision NOT IN ('approve', 'reject') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_decision');
  END IF;

  IF p_decision = 'approve' THEN
    UPDATE app.opportunities
    SET
      review_status = 'approved',
      review_reason = NULL,
      reviewed_at = now(),
      reviewed_by = v_user_id,
      status = 'published',
      is_active = TRUE,
      updated_at = now()
    WHERE id = p_opportunity_id
      AND review_status = 'pending_review'
    RETURNING id INTO v_id;
  ELSE
    UPDATE app.opportunities
    SET
      review_status = 'rejected',
      review_reason = p_reason,
      reviewed_at = now(),
      reviewed_by = v_user_id,
      status = 'draft',
      updated_at = now()
    WHERE id = p_opportunity_id
      AND review_status = 'pending_review'
    RETURNING id INTO v_id;
  END IF;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found_or_not_pending');
  END IF;

  RETURN jsonb_build_object('success', true, 'opportunity_id', v_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_update_opportunity_status(p_opportunity_id uuid, p_status text, p_is_featured boolean, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_opportunity_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    UPDATE app.opportunities
    SET
        status = COALESCE(NULLIF(TRIM(COALESCE(p_status, status)), ''), status),
        is_featured = COALESCE(p_is_featured, is_featured),
        is_active = COALESCE(p_is_active, is_active),
        updated_at = NOW()
    WHERE id = p_opportunity_id
    RETURNING id INTO v_opportunity_id;

    IF v_opportunity_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'opportunity_id', v_opportunity_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_upsert_opportunity_type(p_type_id uuid, p_code text, p_label text, p_sort_order integer, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_type_id UUID;
    v_code TEXT := NULLIF(TRIM(COALESCE(p_code, '')), '');
    v_label TEXT := NULLIF(TRIM(COALESCE(p_label, '')), '');
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF v_code IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_code');
    END IF;

    IF v_label IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_label');
    END IF;

    IF p_type_id IS NULL THEN
        INSERT INTO app.opportunity_types (
            code,
            label,
            sort_order,
            is_active
        )
        VALUES (
            v_code,
            v_label,
            COALESCE(p_sort_order, 0),
            COALESCE(p_is_active, TRUE)
        )
        RETURNING id INTO v_type_id;
    ELSE
        UPDATE app.opportunity_types
        SET
            code = v_code,
            label = v_label,
            sort_order = COALESCE(p_sort_order, sort_order),
            is_active = COALESCE(p_is_active, is_active),
            updated_at = NOW()
        WHERE id = p_type_id
        RETURNING id INTO v_type_id;
    END IF;

    IF v_type_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'type_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'type_id', v_type_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_list_opportunity_inquiry_messages(p_inquiry_id uuid, p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_ok BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT TRUE
  INTO v_ok
  FROM app.opportunity_inquiries i
  WHERE i.id = p_inquiry_id
    AND (i.buyer_id = v_user_id OR i.merchant_id = v_user_id);

  IF v_ok IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'inquiry_not_found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'messages', (
      SELECT COALESCE(
        jsonb_agg(to_jsonb(m) ORDER BY m.created_at ASC),
        '[]'::jsonb
      )
      FROM (
        SELECT id, inquiry_id, sender_id, content, created_at
        FROM app.opportunity_inquiry_messages
        WHERE inquiry_id = p_inquiry_id
          AND (p_before IS NULL OR created_at < p_before)
        ORDER BY created_at DESC
        LIMIT GREATEST(1, LEAST(p_limit, 200))
      ) m
    )
  );
END;
$function$

