CREATE OR REPLACE FUNCTION public.app_opportunity_mark_viewed()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    -- Upsert la date de dernière consultation
    INSERT INTO app.opportunity_views (user_id, last_viewed_at)
    VALUES (v_user_id, NOW())
    ON CONFLICT (user_id) DO UPDATE
    SET last_viewed_at = NOW();

    RETURN JSONB_BUILD_OBJECT('success', TRUE);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_toggle_bookmark(p_opportunity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_exists BOOLEAN;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    -- Vérifier que l'opportunité est toujours valable
    IF NOT EXISTS (
        SELECT 1
        FROM app.opportunities o
        WHERE o.id = p_opportunity_id
          AND o.is_active = TRUE
          AND o.status = 'published'
          AND (o.application_deadline IS NULL OR o.application_deadline >= CURRENT_DATE)
    ) THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_found');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.opportunity_bookmarks b
        WHERE b.opportunity_id = p_opportunity_id
          AND b.user_id = v_user_id
    ) INTO v_exists;

    IF v_exists THEN
        DELETE FROM app.opportunity_bookmarks
        WHERE opportunity_id = p_opportunity_id
          AND user_id = v_user_id;

        RETURN JSONB_BUILD_OBJECT(
            'success', TRUE,
            'action', 'removed',
            'is_bookmarked', FALSE
        );
    ELSE
        INSERT INTO app.opportunity_bookmarks (opportunity_id, user_id)
        VALUES (p_opportunity_id, v_user_id);

        RETURN JSONB_BUILD_OBJECT(
            'success', TRUE,
            'action', 'added',
            'is_bookmarked', TRUE
        );
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_toggle_reaction(p_opportunity_id uuid, p_reaction_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_existing_type TEXT;
    v_new_count INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF p_reaction_type NOT IN ('like', 'love') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_reaction_type');
    END IF;

    -- Vérifier si l'opportunité existe et est active
    IF NOT EXISTS (
        SELECT 1 FROM app.opportunities 
        WHERE id = p_opportunity_id AND is_active = TRUE AND status = 'published'
    ) THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_found');
    END IF;

    -- Vérifier si une réaction existe déjà
    SELECT reaction_type INTO v_existing_type
    FROM app.opportunity_reactions
    WHERE opportunity_id = p_opportunity_id AND user_id = v_user_id;

    IF v_existing_type IS NOT NULL THEN
        IF v_existing_type = p_reaction_type THEN
            -- Même type: supprimer la réaction (toggle off)
            DELETE FROM app.opportunity_reactions
            WHERE opportunity_id = p_opportunity_id AND user_id = v_user_id;

            -- Décrémenter le compteur
            UPDATE app.opportunities 
            SET reactions_count = GREATEST(0, reactions_count - 1), updated_at = NOW()
            WHERE id = p_opportunity_id
            RETURNING reactions_count INTO v_new_count;

            RETURN JSONB_BUILD_OBJECT(
                'success', TRUE, 
                'action', 'removed',
                'my_reaction', NULL,
                'reactions_count', v_new_count
            );
        ELSE
            -- Type différent: mettre à jour
            UPDATE app.opportunity_reactions
            SET reaction_type = p_reaction_type
            WHERE opportunity_id = p_opportunity_id AND user_id = v_user_id;

            SELECT reactions_count INTO v_new_count
            FROM app.opportunities WHERE id = p_opportunity_id;

            RETURN JSONB_BUILD_OBJECT(
                'success', TRUE, 
                'action', 'updated',
                'my_reaction', p_reaction_type,
                'reactions_count', v_new_count
            );
        END IF;
    ELSE
        -- Pas de réaction: en créer une
        INSERT INTO app.opportunity_reactions (opportunity_id, user_id, reaction_type)
        VALUES (p_opportunity_id, v_user_id, p_reaction_type);

        -- Incrémenter le compteur
        UPDATE app.opportunities 
        SET reactions_count = reactions_count + 1, updated_at = NOW()
        WHERE id = p_opportunity_id
        RETURNING reactions_count INTO v_new_count;

        RETURN JSONB_BUILD_OBJECT(
            'success', TRUE, 
            'action', 'added',
            'my_reaction', p_reaction_type,
            'reactions_count', v_new_count
        );
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_apply_for_opportunity(p_opportunity_id uuid, p_message text, p_cv_url text, p_extra_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_opportunity_exists BOOLEAN;
    v_application_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'student' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_student');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.opportunities o
        WHERE o.id = p_opportunity_id
          AND o.is_active = TRUE
          AND o.status = 'published'
          AND (o.application_deadline IS NULL OR o.application_deadline >= CURRENT_DATE)
    ) INTO v_opportunity_exists;

    IF NOT v_opportunity_exists THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_available');
    END IF;

    SELECT id
    INTO v_application_id
    FROM app.opportunity_applications a
    WHERE a.opportunity_id = p_opportunity_id
      AND a.student_id = v_user_id
    LIMIT 1;

    IF v_application_id IS NOT NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'already_applied');
    END IF;

    INSERT INTO app.opportunity_applications (
        opportunity_id,
        student_id,
        message,
        cv_url,
        extra_data,
        status
    )
    VALUES (
        p_opportunity_id,
        v_user_id,
        p_message,
        p_cv_url,
        p_extra_data,
        'submitted'
    )
    RETURNING id INTO v_application_id;

    IF v_application_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_failed');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'application_id', v_application_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_create_opportunity_inquiry(p_opportunity_id uuid, p_message text, p_quantity integer DEFAULT NULL::integer, p_budget numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_merchant_id UUID;
  v_inquiry_id UUID;
  v_is_published BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  IF p_message IS NULL OR length(trim(p_message)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'message_required');
  END IF;

  SELECT o.merchant_id,
         (o.status = 'published' AND o.is_active = TRUE) AS is_published
  INTO v_merchant_id, v_is_published
  FROM app.opportunities o
  WHERE o.id = p_opportunity_id;

  IF v_merchant_id IS NULL OR v_is_published IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'opportunity_not_available');
  END IF;

  INSERT INTO app.opportunity_inquiries(
    opportunity_id, buyer_id, merchant_id, message, quantity, budget, status, created_at, last_message_at
  ) VALUES (
    p_opportunity_id, v_user_id, v_merchant_id, trim(p_message), p_quantity, p_budget, 'open', now(), now()
  ) RETURNING id INTO v_inquiry_id;

  INSERT INTO app.opportunity_inquiry_messages(
    inquiry_id, sender_id, content, created_at
  ) VALUES (
    v_inquiry_id, v_user_id, trim(p_message), now()
  );

  RETURN jsonb_build_object('success', true, 'inquiry_id', v_inquiry_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_list_my_opportunity_inquiries(p_limit integer DEFAULT 30, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'inquiries', (
      SELECT COALESCE(jsonb_agg(to_jsonb(i) ORDER BY i.last_message_at DESC), '[]'::jsonb)
      FROM app.opportunity_inquiries i
      WHERE i.buyer_id = v_user_id
      LIMIT GREATEST(1, LEAST(p_limit, 100))
      OFFSET GREATEST(0, p_offset)
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_reply_opportunity_inquiry(p_inquiry_id uuid, p_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_ok BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  IF p_message IS NULL OR length(trim(p_message)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'message_required');
  END IF;

  SELECT TRUE
  INTO v_ok
  FROM app.opportunity_inquiries i
  WHERE i.id = p_inquiry_id
    AND i.buyer_id = v_user_id;

  IF v_ok IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'inquiry_not_found');
  END IF;

  INSERT INTO app.opportunity_inquiry_messages(inquiry_id, sender_id, content, created_at)
  VALUES (p_inquiry_id, v_user_id, trim(p_message), now());

  UPDATE app.opportunity_inquiries
  SET
    status = 'open',
    last_message_at = now()
  WHERE id = p_inquiry_id;

  RETURN jsonb_build_object('success', true);
END;
$function$
